
mod graph;mod eager;mod pruned;use serde_json::{json,Value};fn main(){let fixtures:Value=serde_json::from_str(include_str!("../fixtures.json")).unwrap();let mut cases=vec![];let mut complete=true;
 for f in fixtures.as_array().unwrap(){let e=eager::original_gstep_fixture(f);let p=pruned::original_gstep_fixture(f);let mut equal=true;let es=e["rows"].as_array().unwrap();let ps=p["rows"].as_array().unwrap();equal&=es.len()==ps.len();for(x,y)in es.iter().zip(ps){for key in["choice","labels","pair","selected","fallback"]{equal&=x[key]==y[key];}equal&=y["evaluated"]==y["selected"];equal&=x["evaluated"]==json!([true,true,true]);}let candidate_pass=!ps.is_empty()&&ps.iter().all(|r|r["pass"]==true);complete&=equal&&candidate_pass;cases.push(json!({"eager":e,"candidate":p,"equal_selected_state":equal,"candidate_pass":candidate_pass}));}
 println!("{}",json!({"schema":"original-gstep-paired-software-integration/v1","cases":cases,"controls":graph::controls(),"complete":complete,"scientific_execution":false}));assert!(complete);}
